package libXray

import (
	"context"
	"encoding/base64"
	"encoding/json"
	"fmt"
	"io"
	"net"
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"
	"testing"
	"time"

	"golang.org/x/net/dns/dnsmessage"
	"golang.org/x/net/proxy"
)

// Uses configurations generated by the real Swift extension transform. Local
// servers report which outbound handled a domain or IP; no iPad/VK is required.
func TestSplitTunnelRoutingPolicies(t *testing.T) {
	directory := os.Getenv("KINDLYVPN_CONFIG_FIXTURES")
	if directory == "" {
		t.Skip("Run Scripts/test-split-routing.sh")
	}
	endpoint := func(marker string) *httptest.Server {
		return httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) { _, _ = io.WriteString(w, marker) }))
	}
	direct, tunneled := endpoint("direct"), endpoint("proxy")
	defer direct.Close()
	defer tunneled.Close()
	dns, err := net.ListenPacket("udp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	defer dns.Close()
	go func() {
		buffer := make([]byte, 4096)
		for {
			n, source, err := dns.ReadFrom(buffer)
			if err != nil {
				return
			}
			var parser dnsmessage.Parser
			header, err := parser.Start(buffer[:n])
			if err != nil {
				continue
			}
			question, err := parser.Question()
			if err != nil {
				continue
			}
			last := byte(20)
			if question.Name.String() == "cdn.test." || question.Name.String() == "selected.test." {
				last = 10
			}
			builder := dnsmessage.NewBuilder(nil, dnsmessage.Header{ID: header.ID, Response: true, RecursionDesired: true, RecursionAvailable: true})
			_ = builder.StartQuestions()
			_ = builder.Question(question)
			_ = builder.StartAnswers()
			if question.Type == dnsmessage.TypeA {
				_ = builder.AResource(dnsmessage.ResourceHeader{Name: question.Name, Class: dnsmessage.ClassINET, TTL: 60}, dnsmessage.AResource{A: [4]byte{203, 0, 113, last}})
			}
			reply, err := builder.Finish()
			if err == nil {
				_, _ = dns.WriteTo(reply, source)
			}
		}
	}()
	freePort := func() int {
		listener, err := net.Listen("tcp", "127.0.0.1:0")
		if err != nil {
			t.Fatal(err)
		}
		port := listener.Addr().(*net.TCPAddr).Port
		_ = listener.Close()
		return port
	}
	for _, mode := range []string{"disabled", "bypassSelected", "tunnelSelected"} {
		t.Run(mode, func(t *testing.T) {
			data, err := os.ReadFile(filepath.Join(directory, mode+".json"))
			if err != nil {
				t.Fatal(err)
			}
			var config map[string]any
			if err := json.Unmarshal(data, &config); err != nil {
				t.Fatal(err)
			}
			socksPort, healthPort := freePort(), freePort()
			config["inbounds"] = []any{
				map[string]any{"tag": "in_proxy", "protocol": "socks", "listen": "127.0.0.1", "port": socksPort, "settings": map[string]any{"auth": "noauth"}},
				map[string]any{"tag": "kindly-health", "protocol": "dokodemo-door", "listen": "127.0.0.1", "port": healthPort, "settings": map[string]any{"address": "unselected.test", "port": 80, "network": "tcp"}},
			}
			freedom := func(tag, address string) map[string]any {
				return map[string]any{"tag": tag, "protocol": "freedom", "settings": map[string]any{"redirect": address}}
			}
			config["outbounds"] = []any{freedom("direct", direct.Listener.Addr().String()), freedom("proxy", tunneled.Listener.Addr().String()), map[string]any{"tag": "block", "protocol": "blackhole"}, map[string]any{"tag": "kindly-dns", "protocol": "dns"}, map[string]any{"tag": "dns-wire", "protocol": "freedom"}}
			// Use local DNS fixtures while preserving the generated domain/tag
			// selection. The HTTP outbound redirects are fixture-only.
			dnsConfig := config["dns"].(map[string]any)
			var servers []any
			for _, raw := range dnsConfig["servers"].([]any) {
				server, ok := raw.(map[string]any)
				if !ok {
					server = map[string]any{"tag": "kindly-dns-query"}
				}
				server["address"], server["port"] = "127.0.0.1", dns.LocalAddr().(*net.UDPAddr).Port
				servers = append(servers, server)
			}
			dnsConfig["servers"] = servers
			routing := config["routing"].(map[string]any)
			routing["rules"] = append([]any{map[string]any{"type": "field", "inboundTag": []string{"kindly-dns-query", "kindly-dns-direct"}, "outboundTag": "dns-wire"}}, routing["rules"].([]any)...)
			file := filepath.Join(t.TempDir(), "routing.json")
			data, _ = json.Marshal(config)
			if err := os.WriteFile(file, data, 0600); err != nil {
				t.Fatal(err)
			}
			request, _ := json.Marshal(runXrayRequest{ConfigPath: file})
			raw, err := base64.StdEncoding.DecodeString(RunXray(base64.StdEncoding.EncodeToString(request)))
			if err != nil {
				t.Fatal(err)
			}
			var result callResponse
			if err := json.Unmarshal(raw, &result); err != nil || !result.Success {
				t.Fatalf("start: %s", raw)
			}
			defer StopXray()
			dialer, err := proxy.SOCKS5("tcp", fmt.Sprintf("127.0.0.1:%d", socksPort), nil, &net.Dialer{Timeout: 3 * time.Second})
			if err != nil {
				t.Fatal(err)
			}
			client := &http.Client{Timeout: 5 * time.Second, Transport: &http.Transport{DisableKeepAlives: true, DialContext: func(ctx context.Context, network, address string) (net.Conn, error) {
				return dialer.(proxy.ContextDialer).DialContext(ctx, network, address)
			}}}
			defer client.CloseIdleConnections()
			for _, target := range []struct {
				address  string
				selected bool
			}{{"selected.test", false}, {"cdn.test", false}, {"manual.test", true}, {"203.0.113.10", true}, {"unselected.test", false}, {"203.0.113.20", false}} {
				expected := "proxy"
				if mode == "bypassSelected" && target.selected || mode == "tunnelSelected" && !target.selected {
					expected = "direct"
				}
				response, err := client.Get("http://" + target.address + "/")
				if err != nil {
					t.Fatalf("%s: %v", target.address, err)
				}
				body, err := io.ReadAll(response.Body)
				_ = response.Body.Close()
				if err != nil || string(body) != expected {
					t.Fatalf("%s used %q; want %q (%v)", target.address, body, expected, err)
				}
				t.Logf("%s -> %s", target.address, body)
			}
			probe := &http.Client{Timeout: 3 * time.Second, Transport: &http.Transport{Proxy: nil, DisableKeepAlives: true}}
			defer probe.CloseIdleConnections()
			response, err := probe.Get(fmt.Sprintf("http://127.0.0.1:%d/", healthPort))
			if err != nil {
				t.Fatal(err)
			}
			body, err := io.ReadAll(response.Body)
			_ = response.Body.Close()
			if err != nil || string(body) != "proxy" {
				t.Fatalf("health bypassed tunnel: %q, %v", body, err)
			}
		})
	}
}
